  if (w.kind === "price") h += `<div class="ha-bill" dir="ltr">${w.days.map((d, i) => { const r = recs[i]; return `<div class="r"><span>${d.e} ${esc(tx(d.t))}</span><span>${r ? (r.pr ? esc(fmt(r.pr[0], r.pr[1])) : "✓") : DEMO ? sample() : i > o.i ? "🔒" : "·"}</span></div>`; }).join("")}<div class="r t"><span>${esc(T("我说了", "Said"))}</span><span>${DEMO ? n + " " + sample() : got} / ${n}</span></div></div>`;
